command:
// Ensure an actor is selected
let actor = canvas.tokens.controlled[0]?.actor;
if (!actor) {
    ui.notifications.warn("No actor selected!");
    return;
}

// Function to extract dice roll from the effect name
function extractDice(effectName) {
    let diceMatch = effectName.match(/1d[468] Speed/);
    return diceMatch ? diceMatch[0].split(' ')[0] : null;
}

// Function to extract speed penalty from the effect name
function extractSpeedPenalty(effectName) {
    let penaltyMatch = effectName.match(/Penalty (\d+)/);
    return penaltyMatch ? parseInt(penaltyMatch[1]) : 0;
}

// Search for the speed dice effect and speed penalty
let speedDice = null;
let speedPenalty = 0;
actor.items.forEach(effect => {
    if (!speedDice && /1d[468] Speed/.test(effect.name)) {
        speedDice = extractDice(effect.name);
    }
    if (/Speed Penalty/.test(effect.name)) {
        speedPenalty = Math.max(speedPenalty, extractSpeedPenalty(effect.name));
    }
});

// Prompt the user if a speed dice effect is found
if (speedDice) {
    const bonus = await foundry.applications.api.DialogV2.wait({
        window: { title: "Roll Speed Dice" },
        content: `
            <p>Roll ${speedDice} for speed? Speed Penalty: ${speedPenalty}</p>
            <div><input type="checkbox" id="small-vehicle-bonus" name="smallVehicleBonus"><label for="small-vehicle-bonus">Small vehicle bonus?</label></div>
        `,
        buttons: [
            {
                action: "roll",
                icon: "fas fa-dice",
                label: "Roll",
                callback: (_event, button) => button.form.querySelector('[name="smallVehicleBonus"]').checked ? 2 : 0
            },
            {
                action: "cancel",
                icon: "fas fa-times",
                label: "Cancel",
                default: true,
                callback: () => null
            }
        ],
        rejectClose: false
    });
    if (bonus === null) return;
    const roll = await new foundry.dice.Roll(`${speedDice} - ${speedPenalty} + ${bonus}`).evaluate();
    await roll.toMessage({ flavor: `Rolling ${speedDice} (Speed Penalty: ${speedPenalty}, Small Vehicle Bonus: ${bonus})` });
} else {
    ui.notifications.warn("No '1d4 Speed', '1d6 Speed', or '1d8 Speed' effect found on the actor.");
}
